
print("=== Simple LLM Workflow Demo ===")

prompt = input("Enter a prompt: ")

# Simplified tokenization for demonstration
tokens = prompt.split()

print("\n1. User Prompt:")
print(prompt)

print("\n2. Whitespace-Based Tokens:")
print(tokens)
print("Token Count:", len(tokens))

# Illustrative response, not generated by a real LLM
example_response = (
    "This demonstration shows how a prompt can be "
    "split into simple text units before processing."
)

print("\n3. Example Response:")
print(example_response)

print("\nNote: This is a simulation, not a real LLM.")